mapper.select:
select c.id, c.name, c.room, c.begin_date, c.end_date, c.master_id, e.name as master_name, c.create_time, c.update_time, case when c.end_date < curdate() then '已结课' when c.begin_date > curdate() then '未开班' else '在读' end as status from clazz c left join emp e on c.master_id = e.id
and c.name like concat('%', #{name}, '%')
and c.begin_date >= #{begin}
and c.end_date <= #{end}
order by c.update_time desc
